window.SAP_CH_DATA = {"id":"ch_65","title":"Xuất chuyển kho","start_page":567,"end_page":572,"slides":[{"page":567,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n26\n❑App thực hiện: PDA – Xuất kho lệnh xuất kho\nBước 1: \nChọn app Xuất kho lệnh xuất \nkho trên PDA\nBước 2:\nNgười dùng chọn lệnh xuất \nchuyển kho đã tạo\nĐối với thiết bị PDA chuyên \ndụng, người dùng có thể nhấn \nvào nút Scan của máy để quét \nID Pallet/ ID hàng\nĐối với thiết bị điện thoại, \nngười dùng có thể nhấn vào \nnút Camera để quét ID Pallet/ \nID hàng\n✓Thực hiện Xuất kho trên PDA\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":["","",""]},{"page":568,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n27\nSau khi người dùng quét ID \nPallet, trên PDA check và ghi \nnhận đủ số lượng so với số \nlượng gợi ý, PDA sẽ hiển thị \nmàu xanh\n✓Thực hiện Xuất kho trên PDA\n❑App thực hiện: PDA – Xuất kho lệnh xuất kho\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":["",""]},{"page":569,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n28\n❑App thực hiện: Xuất kho\nBước 3:\nNhập app: “Xuất kho” vào \nthanh tìm kiếm\nBước 4: \nClick chọn vào app Xuất kho\n✓Xuất kho trên SAP\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]},{"page":570,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n29\n❑App thực hiện: Xuất kho\nBước 5: \nĐiền lệnh xuất hàng tổng ở \ntham số để lọc dữ liệu\nBước 6:\nNhấn Go để lọc dữ liệu cần \ntìm \n✓Xuất kho trên SAP\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]},{"page":571,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n30\n❑App thực hiện: Xuất kho\nBước 7: \nThực hiện chọn tất cả các \ndòng của lệnh xuất hàng tổng \nvừa thực hiện Pick hàng\nBước 8:\nNhấn Check để kiểm tra dữ \nliệu\nBước 9:\nSau khi nhấn Check và dữ liệu \nkhông còn sai sót, tiếp tục \nnhấn Post để tạo giao dịch \ntrên hệ thống\n \n✓Xuất kho trên SAP\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]},{"page":572,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n31\n❑App thực hiện: Xuất kho\nPost thành công, tồn kho \nđược xuất khỏi hệ thống\n \n✓Xuất kho trên SAP\nWM.05D.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nTHÀNH PHẨM QUA LẠI GIỮA CÁC KHO TRONG NHÀ MÁY (WM – WM: CÓ \nBARCODE)","images":[""]}]};